from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class BwpProfileParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        if self.mo_num == '0' or self.mo_num == '2':
            self.set_parameter('bwpType', 'initial')
            self.set_struct_parameter('locationAndBandwidthDl', 'cRbSizeDl', 'coreset0')
            self.set_struct_parameter('locationAndBandwidthDl', 'cRbStartDl', 'coreset0')
            self.set_struct_parameter('locationAndBandwidthUl', 'cRbSizeUl', 'sameAsDl')
            self.set_struct_parameter('locationAndBandwidthUl', 'cRbStartUl', 'sameAsDl')
        elif self.mo_num == '1' or self.mo_num == '3':
            self.set_parameter('bwpType', 'dedicated')
            self.set_struct_parameter('locationAndBandwidthDl', 'cRbSizeDl', 'allRb')
            if self.is_sa_nsa:
                self.set_struct_parameter('locationAndBandwidthDl', 'cRbStartDl', 'coreset0')
            else:
                self.set_struct_parameter('locationAndBandwidthDl', 'cRbStartDl', 'crb0')
            self.set_struct_parameter('locationAndBandwidthUl', 'cRbSizeUl', 'sameAsDl')
            self.set_struct_parameter('locationAndBandwidthUl', 'cRbStartUl', 'sameAsDl')
